// 获取输入
const body = $input.body;
const username = body.username;
const password = body.password;
const name = body.name || username;

// 1) 用户名：仅字母数字
const usernameRegex = /^[a-zA-Z0-9]+$/;
if (!usernameRegex.test(username)) {
  throw new Error("Invalid username. Only alphanumeric characters allowed.");
}

// 2) 密码：8-64 长度，允许常见符号，禁止引号/反引号/空格，降低命令注入风险
const passwordRegex = /^[A-Za-z0-9!@#$%^&*()_+=\-.,:;?/]{8,64}$/;
if (!passwordRegex.test(password)) {
  throw new Error("Password must be 8-64 chars; allowed: letters, numbers, !@#$%^&*()_+=-.,:;?/");
}

// 3) 显示名称：限制为常见安全字符
const nameRegex = /^[A-Za-z0-9 _.-]{1,64}$/;
if (!nameRegex.test(name)) {
  throw new Error("Name must be 1-64 chars; allowed letters, numbers, space, _ . -");
}

return {
  json: {
    safeUsername: username,
    safePassword: password,
    safeName: name.trim()
  }
};
